import { Injectable } from '@angular/core';
import { TostbarService } from '../../../core/services/tost/tostbar.service';
import { HttpClient, HttpParams } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { SectionBuilderRes, SectionBuilderReq, SectionRes, UserSectionBuilderReq } from '../../interfaces/bundlemanage.interface';
import { environment } from '../../../../environments/environment';
import { ErrorHandlerUtil } from '../../../userpanel/utility/error-handler.util';

@Injectable({
  providedIn: 'root'
})
export class BundlemanageService {

  private readonly coreServiceUrl = `${environment.cloudUrl}${environment.coreservice}`;

  constructor(
    private readonly http: HttpClient,
    private readonly tost: TostbarService
  ) { }

  private notifyRequestError(action: string, err: unknown): void {
    const message = ErrorHandlerUtil.getErrorMessage(err);
    this.tost.error(message && message !== 'Unknown error' ? `${action} failed: ${message}` : `${action} failed`);
  }

  async getSections(nCaseid: string): Promise<SectionRes[]> {
    try {
      const params = new HttpParams().set('nCaseid', nCaseid);
      return await firstValueFrom(
        this.http.get<SectionRes[]>(`${this.coreServiceUrl}/bundles/sections`, { params })
      );
    } catch (err: unknown) {
      this.notifyRequestError('Get sections', err);
      return [];
    }
  }


  async sectionBuilder(mdl: SectionBuilderReq): Promise<boolean> {
    try {
      const res = await firstValueFrom(
        this.http.post<SectionBuilderRes>(`${this.coreServiceUrl}/bundles-creations/sectionbuilder`, mdl)
      );
      if (res?.msg === 1) {
        this.tost.openSnackBar(res.value, '');
        return true;
      } else {
        this.tost.openSnackBar(res.value, 'E');
        return false;
      }
    } catch (err: unknown) {
      this.notifyRequestError('Section creation', err);
      return false;
    }
  }

  async getUserSections(nCaseid: string): Promise<SectionRes[][]> {
    try {
      const params = new HttpParams().set('nCaseid', nCaseid);
      return await firstValueFrom(
        this.http.get<SectionRes[][]>(`${this.coreServiceUrl}/bundles/usersections`, { params })
      );
    } catch (err: unknown) {
      this.notifyRequestError('Get user sections', err);
      return [];
    }
  }

  async getUploadSections(nCaseid: string): Promise<SectionRes[][]> {
    try {
      const params = new HttpParams().set('nCaseid', nCaseid);
      return await firstValueFrom(
        this.http.get<SectionRes[][]>(`${this.coreServiceUrl}/bundles/uploadsections`, { params })
      );
    } catch (err: unknown) {
      this.notifyRequestError('Get upload sections', err);
      return [];
    }
  }

  async usersectionBuilder(mdl: UserSectionBuilderReq): Promise<boolean> {
    try {
      const res = await firstValueFrom(
        this.http.post<SectionBuilderRes>(`${this.coreServiceUrl}/bundles-creations/usersectionbuilder`, mdl)
      );
      if (res?.msg === 1) {
        this.tost.openSnackBar(res.value, '');
        return true;
      } else {
        this.tost.openSnackBar(res.value, 'E');
        return false;
      }
    } catch (err: unknown) {
      this.notifyRequestError('User section creation', err);
      return false;
    }
  }



  async getConvertingLength(nCaseid: string): Promise<{ queueLength: number }> {
    try {
      const params = new HttpParams().set('nCaseid', nCaseid);
      const res = await firstValueFrom(
        this.http.get<{ queueLength: number }>(
          `${environment.uploadservice}/fileconvert/convertlength`,
          { params }
        )
      );

      return res;
    } catch (err: unknown) {
      this.notifyRequestError('Get converting length', err);
      return { queueLength: 0 };
    }
  }

}



